(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x * 0.018 + t * 0.25) * 20 + Math.cos(y * 0.013 - t * 0.18) * 14;
  const w1y = Math.cos(y * 0.016 - t * 0.22) * 18 + Math.sin(x * 0.014 + t * 0.3) * 12;
  const w2x = Math.sin((x + y) * 0.01 + t * 0.15) * 8;
  const w2y = Math.cos((x - y) * 0.012 - t * 0.2) * 8;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
