  const n = 8;
  const act = aS/n, inh = iS/n, crs = cross/n;
  const fbm1 = Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1)*0.7 + Math.sin(sx*0.08+sy*0.06-t*1.5)*0.35 + Math.sin(sx*0.15-sy*0.1+t*2.2)*0.15;
