  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2) + Math.sin(dist*0.08-ang*2+t*0.8)*0.5) / 2.5;
  const lapA = Math.sin((sx+1)*0.15)*Math.sin(sy*0.15) + Math.sin((sx-1)*0.15)*Math.sin(sy*0.15) + Math.sin(sx*0.15)*Math.sin((sy+1)*0.15) + Math.sin(sx*0.15)*Math.sin((sy-1)*0.15) - 4*Math.sin(sx*0.15)*Math.sin(sy*0.15);
