  const diffA = Math.tanh(act*0.8 - inh*0.6 + crs*0.3 + bg*0.25 + spiral*0.35 + lapA*0.15);
  const diffI = Math.tanh(-act*0.3 + inh*0.5 + crs*0.2 + bg*0.15 - spiral*0.2 + lapI*0.12);
